    res.purchase.installments ? `🔢 Parcelas: *${res.purchase.installments}x*` : ''
  ].filter(Boolean).join('\n');
}
if (res.code === 'PURCHASE_DELETED') text = res.whatsapp?.text || '🗑️ Compra apagada com sucesso.';
return [{ json: { ...res, outbound_text: text } }];

